"use client"

import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "cn"

import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"

// agentui: no fill in dark, its border alone (3:1) outlining it, so a
// field is not a grey slab on a card or a dialog.
function InputGroup({
  className,
  size = "default",
  ...props
}: React.ComponentProps<"div"> & {
  /**
   * agentui: `"lg"`, a sign-in screen's: 44px, a finger's height, its
   * text 16px and its icons 20px.
   */
  size?: "default" | "lg"
}) {
  // agentui: the group looks disabled when its control is, not when any
  // descendant is (a disabled send button left the field looking disabled).
  // agentui: a contenteditable control is :focus-visible whenever it has
  // focus, pointer or not, so it does not take the dark border and 3px ring
  // a keyboard focus gets; its border darkens a step instead, still a
  // visible focus indicator.
  return (
    <div
      data-slot="input-group"
      data-size={size}
      role="group"
      className={cn(
        "group/input-group relative flex h-8 w-full min-w-0 items-center rounded-lg border border-field transition-colors outline-none in-data-[slot=combobox-content]:focus-within:border-inherit in-data-[slot=combobox-content]:focus-within:ring-0 has-[[data-slot=input-group-control]:disabled]:bg-input/50 has-[[data-slot=input-group-control]:disabled]:opacity-50 has-[[data-slot=input-group-control]:focus-visible]:border-ring has-[[data-slot=input-group-control]:focus-visible]:ring-3 has-[[data-slot=input-group-control]:focus-visible]:ring-ring/50 has-[[data-slot=input-group-control][contenteditable]:focus-visible]:border-ring/50 has-[[data-slot=input-group-control][contenteditable]:focus-visible]:ring-0 has-[[data-slot][aria-invalid=true]]:border-destructive has-[[data-slot][aria-invalid=true]]:ring-3 has-[[data-slot][aria-invalid=true]]:ring-destructive/20 has-[>[data-align=block-end]]:h-auto has-[>[data-align=block-end]]:flex-col has-[>[data-align=block-start]]:h-auto has-[>[data-align=block-start]]:flex-col has-[>textarea]:h-auto dark:has-[[data-slot=input-group-control]:disabled]:bg-input/80 dark:has-[[data-slot][aria-invalid=true]]:ring-destructive/40 has-[>[data-align=block-end]]:[&>input]:pt-3 has-[>[data-align=block-start]]:[&>input]:pb-3 has-[>[data-align=inline-end]]:[&>input]:pr-2 has-[>[data-align=inline-start]]:[&>input]:pl-2",
        size === "lg" &&
          "h-11 rounded-xl [&_[data-slot=input-group-control]]:text-base [&_[data-slot=input-group-addon]_svg:not([class*='size-'])]:size-5",
        className
      )}
      {...props}
    />
  )
}

const inputGroupAddonVariants = cva(
  "flex h-auto cursor-text items-center justify-center gap-2 py-1 text-sm font-medium text-muted-foreground select-none group-data-[disabled=true]/input-group:opacity-50 [&>kbd]:rounded-[calc(var(--radius)-5px)] [&>svg:not([class*='size-'])]:size-4",
  {
    variants: {
      align: {
        "inline-start":
          "order-first pl-2 has-[>button]:ml-[-0.3rem] has-[>kbd]:ml-[-0.15rem]",
        "inline-end":
          "order-last pr-2 has-[>button]:mr-[-0.3rem] has-[>kbd]:mr-[-0.15rem]",
        "block-start":
          "order-first w-full justify-start px-3 pt-2 group-has-[>input]/input-group:pt-2 [.border-b]:pb-2",
        "block-end":
          "order-last w-full justify-start px-3 pb-2 group-has-[>input]/input-group:pb-2 [.border-t]:pt-2",
      },
    },
    defaultVariants: {
      align: "inline-start",
    },
  }
)

function InputGroupAddon({
  className,
  align = "inline-start",
  ...props
}: React.ComponentProps<"div"> & VariantProps<typeof inputGroupAddonVariants>) {
  return (
    <div
      role="group"
      data-slot="input-group-addon"
      data-align={align}
      className={cn(inputGroupAddonVariants({ align }), className)}
      onClick={(e) => {
        if ((e.target as HTMLElement).closest("button")) {
          return
        }
        e.currentTarget.parentElement?.querySelector("input")?.focus()
      }}
      {...props}
    />
  )
}

const inputGroupButtonVariants = cva(
  "flex items-center gap-2 text-sm shadow-none",
  {
    variants: {
      size: {
        xs: "h-6 gap-1 rounded-[calc(var(--radius)-3px)] px-2 [&>svg:not([class*='size-'])]:size-3.5",
        sm: "",
        "icon-xs":
          "size-6 rounded-[calc(var(--radius)-3px)] p-0 has-[>svg]:p-0",
        "icon-sm": "size-8 p-0 has-[>svg]:p-0",
      },
    },
    defaultVariants: {
      size: "xs",
    },
  }
)

function InputGroupButton({
  className,
  type = "button",
  variant = "ghost",
  size = "xs",
  ...props
}: Omit<React.ComponentProps<typeof Button>, "size" | "type"> &
  VariantProps<typeof inputGroupButtonVariants> & {
    type?: "button" | "submit" | "reset"
  }) {
  return (
    <Button
      type={type}
      data-size={size}
      variant={variant}
      className={cn(inputGroupButtonVariants({ size }), className)}
      {...props}
    />
  )
}

function InputGroupText({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      className={cn(
        "flex items-center gap-2 text-sm text-muted-foreground [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4",
        className
      )}
      {...props}
    />
  )
}

function InputGroupInput({
  className,
  ...props
}: React.ComponentProps<"input">) {
  return (
    <Input
      data-slot="input-group-control"
      className={cn(
        "flex-1 rounded-none border-0 bg-transparent shadow-none ring-0 focus-visible:ring-0 disabled:bg-transparent aria-invalid:ring-0 dark:bg-transparent dark:disabled:bg-transparent",
        className
      )}
      {...props}
    />
  )
}

function InputGroupTextarea({
  className,
  ...props
}: React.ComponentProps<"textarea">) {
  return (
    <Textarea
      data-slot="input-group-control"
      className={cn(
        "flex-1 resize-none rounded-none border-0 bg-transparent py-2 shadow-none ring-0 focus-visible:ring-0 disabled:bg-transparent aria-invalid:ring-0 dark:bg-transparent dark:disabled:bg-transparent",
        className
      )}
      {...props}
    />
  )
}

// agentui: a popup opened from inside a group, as a menu of a composer's
// toolbar, sits 8px clear of the whole group rather than of its trigger,
// so it never covers the text: Base UI's `sideOffset` for it, given its
// trigger, e.g. `sideOffset={({ side }) => inputGroupPopupOffset(
// trigger.current, side)}`; `outside` a group, its usual offset. A group
// marked `data-popups="trigger"` has its popups by their triggers, the
// usual offset from them.
function inputGroupPopupOffset(
  trigger: Element | null,
  side: string,
  outside = 4
) {
  const group = trigger?.closest<HTMLElement>("[data-slot=input-group]")
  if (!trigger || !group || group.dataset.popups === "trigger") return outside
  const from = inputGroupPopupAnchor(trigger)!.getBoundingClientRect()
  const to = group.getBoundingClientRect()
  if (side === "top") return from.top - to.top + 8
  if (side === "bottom") return to.bottom - from.bottom + 8
  return outside
}

// agentui: what such a popup is placed by, Base UI's `anchor`, e.g.
// `anchor={() => inputGroupPopupAnchor(trigger.current)}`: its trigger,
// or where the group has folded the trigger away (a narrow composer's
// toolbar), the group's button marked `data-input-group-fold` that stands
// for it.
function inputGroupPopupAnchor(trigger: Element | null) {
  if (!trigger || trigger.getClientRects().length > 0) return trigger
  return (
    trigger
      .closest("[data-slot=input-group]")
      ?.querySelector("[data-input-group-fold]") ?? trigger
  )
}

// agentui: for a popup aligned to its trigger's end (`align="end"`), the
// `alignOffset` that ends it where the group's end column starts, the
// first element marked `data-input-group-end` (a composer's stop and
// send) after the trigger; 0 without one.
function inputGroupPopupEndOffset(trigger: Element | null) {
  const from = inputGroupPopupAnchor(trigger)
  const group = trigger?.closest("[data-slot=input-group]")
  const end = group?.querySelector("[data-input-group-end]")
  if (!from || !group || !end) return 0
  const a = from.getBoundingClientRect()
  const b = end.getBoundingClientRect()
  const rtl = getComputedStyle(group).direction === "rtl"
  const by = rtl ? a.left - b.right : b.left - a.right
  return by > 0 ? -by : 0
}

export {
  inputGroupPopupAnchor,
  inputGroupPopupEndOffset,
  inputGroupPopupOffset,
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupText,
  InputGroupInput,
  InputGroupTextarea,
}
